BEGIN IMMEDIATE;
CREATE TABLE api_credentials(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,key_id TEXT NOT NULL,subject_id TEXT NOT NULL,subject_kind TEXT NOT NULL,revocation_epoch INTEGER NOT NULL CHECK(revocation_epoch>=0),expires_at_ms INTEGER NOT NULL,disabled INTEGER NOT NULL CHECK(disabled IN (0,1)),password_hash TEXT NOT NULL CHECK(length(password_hash)<=256),created_by TEXT NOT NULL,operation_id TEXT NOT NULL,request_digest TEXT NOT NULL CHECK(length(request_digest)=64),PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,key_id),UNIQUE(organization_id,tenant_id,project_id,agent_uid,created_by,operation_id),FOREIGN KEY(tenant_id,subject_id) REFERENCES principals(tenant_id,subject_id));
CREATE TABLE credential_revocations(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,key_id TEXT NOT NULL,operation_id TEXT NOT NULL,actor_id TEXT NOT NULL,result_json TEXT NOT NULL CHECK(length(result_json)<=4096),PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,operation_id));
CREATE TRIGGER immutable_api_credential_delete BEFORE DELETE ON api_credentials BEGIN SELECT RAISE(ABORT,'immutable credential'); END;
CREATE TRIGGER immutable_api_credential_update BEFORE UPDATE ON api_credentials WHEN OLD.disabled>NEW.disabled OR OLD.organization_id<>NEW.organization_id OR OLD.tenant_id<>NEW.tenant_id OR OLD.project_id<>NEW.project_id OR OLD.agent_uid<>NEW.agent_uid OR OLD.key_id<>NEW.key_id OR OLD.subject_id<>NEW.subject_id OR OLD.subject_kind<>NEW.subject_kind OR OLD.revocation_epoch<>NEW.revocation_epoch OR OLD.expires_at_ms<>NEW.expires_at_ms OR OLD.password_hash<>NEW.password_hash OR OLD.created_by<>NEW.created_by OR OLD.operation_id<>NEW.operation_id OR OLD.request_digest<>NEW.request_digest BEGIN SELECT RAISE(ABORT,'immutable credential'); END;
CREATE TRIGGER immutable_credential_revocation_update BEFORE UPDATE ON credential_revocations BEGIN SELECT RAISE(ABORT,'immutable revocation'); END;
CREATE TRIGGER immutable_credential_revocation_delete BEFORE DELETE ON credential_revocations BEGIN SELECT RAISE(ABORT,'immutable revocation'); END;
INSERT INTO schema_migrations VALUES(31,CAST(strftime('%s','now') AS INTEGER)*1000);
COMMIT;
